const id=n=>`${n.repeat(8)}-${n.repeat(4)}-4${n.repeat(3)}-8${n.repeat(3)}-${n.repeat(12)}`;
// September 2026 app-shell sidebar: the UUID lives on a draggable listitem, not an anchor.
const modernRow=(n,key=`chatgpt:conversation:${id(n)}`)=>`<div role="listitem" data-sidebar-chatgpt-conversation-key="${key}"><div style="height:auto;opacity:1;overflow:visible"><div role="button" tabindex="0" aria-label="Chat ${n}"><div class="contents"><button aria-haspopup="menu">Chat actions</button><button>Pin chat</button></div><div class="title"><span>Chat ${n}</span></div></div></div></div>`;
const modernSidebar=()=>`<aside><div id="app-shell-sidebar"><nav aria-label="Home"><div data-app-action-sidebar-scroll><section data-app-action-sidebar-section-heading="Projects"><button data-app-action-sidebar-section-toggle>Projects</button><div role="button" data-app-action-sidebar-project-id="g-p-test">Project</div></section><section data-app-action-sidebar-section-heading="Recents"><div class="header"><div><button data-app-action-sidebar-section-toggle>最近</button></div><button aria-haspopup="menu">Chat sidebar options</button></div><div role="list">${modernRow('1')}${modernRow('2')}${modernRow('3','work:task:'+id('3'))}${modernRow('4','chatgpt:conversation:invalid')}</div></section></div></nav></div></aside><main>${modernRow('5')}<a href="/c/${id('6')}">Reference</a></main>`;
const modernRail=()=>`<nav data-app-navigation-rail="true" aria-label="Application navigation"><div aria-hidden="true"></div><div class="rail-items"><div><button data-sidebar-destination="builtin:home">Home</button></div><button data-sidebar-destination="builtin:library">Library</button><button aria-haspopup="dialog" data-slot="popover-trigger">Explore</button></div><div><button>Profile</button></div></nav>`;
module.exports={modernRow,modernSidebar,modernRail};
